INSERT INTO _migration_509_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bghl_culture_s2_001', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, '“Anansesem” are traditional Akan stories that usually feature which character?', 'multiple_choice', NULL, '["A. Kwaku Ananse, the spider","B. The lion, king of the forest","C. The crocodile of the river","D. A magical talking drum"]', 'A', 'Anansesem are folktales built around Kwaku Ananse, the clever and tricky spider whose exploits teach moral lessons. Lions, crocodiles and drums appear in some tales, but the central character of anansesem is the spider. Therefore the correct answer is A: Kwaku Ananse, the spider.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_culture_s2_002', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What is “mpaebo” in Akan custom?', 'multiple_choice', NULL, '["A. A naming ceremony for a baby","B. The pouring of libation — offering drink with prayers to God and the ancestors","C. A funeral dance","D. A harvest meal"]', 'B', 'Mpaebo is the pouring of libation: drink is poured while prayers are said to God (Onyankopɔn), the earth and the ancestors to open important occasions. A naming ceremony is abadinto, so that option belongs to a different rite. Therefore the correct answer is B: The pouring of libation — offering drink with prayers to God and the ancestors.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_culture_s2_003', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'A boy born on a Monday among the Akan is commonly given which day-name?', 'multiple_choice', NULL, '["A. Kwabena","B. Kofi","C. Kwadwo","D. Kwame"]', 'C', 'Monday-born boys are called Kwadwo (and girls Adwoa). Kwabena is Tuesday, Kofi is Friday and Kwame is Saturday, so the other names belong to different days. Therefore the correct answer is C: Kwadwo.', 'easy', '2', '1', '60', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO1', NULL, NULL, 'board_waec'),
('q_bghl_culture_s2_004', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'A girl born on a Sunday among the Akan is commonly named...', 'multiple_choice', NULL, '["A. Adwoa","B. Yaa","C. Ama","D. Akosua"]', 'D', 'Sunday-born girls are Akosua (boys are Kwesi). Adwoa is Monday, Yaa is Thursday and Ama is Saturday, so those names belong to other days of the week. Therefore the correct answer is D: Akosua.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_culture_s2_005', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'The Aboakyer festival of the Effutu people of Winneba is famous for what?', 'multiple_choice', NULL, '["A. The hunt for a live deer, which is offered to their god","B. Hooting at hunger with sprinkled mashed food","C. The first eating of the new yam","D. A canoe race on the sea"]', 'A', 'At Aboakyer, two warrior groups compete to catch a live deer and present it to the god Penkye Otu. Hooting at hunger describes the Ga Homowo festival, so that distractor belongs to a different celebration. Therefore the correct answer is A: The hunt for a live deer, which is offered to their god.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_culture_s2_006', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, '“Homowo”, the festival whose name means “hooting at hunger”, belongs to which people?', 'multiple_choice', NULL, '["A. The Asante people","B. The Ga people","C. The Ewe people","D. The Dagomba people"]', 'B', 'Homowo is the festival of the Ga people of Accra, celebrating the end of a historic famine: kpokpoi (a special dish) is sprinkled while hunger is hooted at and mocked. The Asante celebrate Adae, so the other peoples are distractors. Therefore the correct answer is B: The Ga people.', 'medium', '3', '1', '90', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO2', NULL, NULL, 'board_waec'),
('q_bghl_culture_s2_007', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'What is the role of the “okyeame” in an Akan chief’s court?', 'multiple_choice', NULL, '["A. The lead drummer of the atumpan drums","B. The chief’s eldest son and heir","C. The linguist who relays, polishes and speaks on behalf of the chief","D. The priest who pours libation"]', 'C', 'The okyeame is the chief’s linguist and spokesperson: visitors speak through him, and he repeats and adorns the chief’s words with proverbs. Drumming, succession and libation belong to other office holders in the court. Therefore the correct answer is C: The linguist who relays, polishes and speaks on behalf of the chief.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Identify', 'AO3', NULL, NULL, 'board_waec'),
('q_bghl_culture_s2_008', 'topic_bece_ghlang_culture', 'subj_bece_gh_lang', 'exam_bece', NULL, NULL, 'Why are the atumpan called “talking drums”?', 'multiple_choice', NULL, '["A. They have recorded human voices hidden inside them","B. They are beaten only at funeral dances","C. They can be heard by everyone over long distances","D. Their tones imitate the pitch patterns of speech, so skilled drummers can send messages and praise names"]', 'D', 'Because Akan is a tonal language, the high and low tones of the atumpan can mirror the pitch of spoken phrases, allowing drummers to “speak” proverbs, praise names and announcements. The drums contain no voices, and being loud alone would not make them “talk”. Therefore the correct answer is D: Their tones imitate the pitch patterns of speech, so skilled drummers can send messages and praise names.', 'hard', '4', '1', '120', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT INTO _migration_509_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_509_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_509_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_509_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-ghlang-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_509_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_509_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_509_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 8 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_509_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-ghlang-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to Ghana''s published NaCCA Common Core Programme Ghanaian Language curriculum; not official WAEC or NaCCA examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 8 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_509_expected e ON e.id = q.id) = 8 AND (SELECT COUNT(*) FROM questions q JOIN subjects s ON s.id = q.subject_id AND s.exam_type_id = q.exam_type_id JOIN _migration_509_expected e ON e.id = q.id) = 8 THEN 1 ELSE 0 END;
